sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (current.getValue('active') != 'true') {
        return;
    }

    var duplicate = new GlideRecord('x_2130921_caresy_0_care_plan');

    duplicate.addQuery('patient', current.getValue('patient'));
    duplicate.addQuery('admission', current.getValue('admission'));
    duplicate.addQuery('care_plan_type', current.getValue('care_plan_type'));
    duplicate.addQuery('active', true);
    duplicate.addQuery('sys_id', '!=', current.getUniqueValue());
    duplicate.query();

    if (duplicate.next()) {

        gs.addErrorMessage(
            'An active Care Plan of the same type already exists for this Patient and Admission.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
